use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut left: Vec<int> = []
    let mut right: Vec<int> = []
    let mut root: int = -1
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        let mut x: int = 0
        if parts.len() > 1 {
            x = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            if root < 0 {
                keys.push(x)
                left.push(-1)
                right.push(-1)
                root = (keys.len() as int) - 1
                println("ok")
            } else {
                let mut cur = root
                let mut done = false
                while !done {
                    let k = keys[cur as usize]
                    if x == k {
                        println("dup")
                        done = true
                    } else {
                        let go_left = x < k
                        let nxt = if go_left { left[cur as usize] } else { right[cur as usize] }
                        if nxt < 0 {
                            keys.push(x)
                            left.push(-1)
                            right.push(-1)
                            let id = (keys.len() as int) - 1
                            if go_left {
                                left[cur as usize] = id
                            } else {
                                right[cur as usize] = id
                            }
                            println("ok")
                            done = true
                        } else {
                            cur = nxt
                        }
                    }
                }
            }
        } else if cmd == "contains" {
            let mut cur = root
            let mut found = false
            while cur >= 0 && !found {
                let k = keys[cur as usize]
                if x == k {
                    found = true
                } else if x < k {
                    cur = left[cur as usize]
                } else {
                    cur = right[cur as usize]
                }
            }
            if found { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let mut cur = root
            let mut parent: int = -1
            let mut found = false
            while cur >= 0 && !found {
                let k = keys[cur as usize]
                if x == k {
                    found = true
                } else {
                    parent = cur
                    if x < k {
                        cur = left[cur as usize]
                    } else {
                        cur = right[cur as usize]
                    }
                }
            }
            if !found {
                println("missing")
            } else {
                let l = left[cur as usize]
                let r = right[cur as usize]
                if l >= 0 && r >= 0 {
                    let mut sp = cur
                    let mut s = r
                    while left[s as usize] >= 0 {
                        sp = s
                        s = left[s as usize]
                    }
                    keys[cur as usize] = keys[s as usize]
                    let sr = right[s as usize]
                    if sp == cur {
                        right[sp as usize] = sr
                    } else {
                        left[sp as usize] = sr
                    }
                } else {
                    let child = if l >= 0 { l } else { r }
                    if parent < 0 {
                        root = child
                    } else if left[parent as usize] == cur {
                        left[parent as usize] = child
                    } else {
                        right[parent as usize] = child
                    }
                }
                println("ok")
            }
        } else if cmd == "inorder" {
            let mut out: Vec<string> = []
            let mut stack: Vec<int> = []
            let mut cur = root
            while cur >= 0 || stack.len() > 0 {
                while cur >= 0 {
                    stack.push(cur)
                    cur = left[cur as usize]
                }
                let n = stack.pop().unwrap_or(0)
                out.push("${keys[n as usize]}")
                cur = right[n as usize]
            }
            if out.len() == 0 { println("<empty>") } else { println(out.join(" ")) }
        } else if cmd == "height" {
            let mut best: int = 0
            let mut nodes: Vec<int> = []
            let mut depths: Vec<int> = []
            if root >= 0 {
                nodes.push(root)
                depths.push(1)
            }
            while nodes.len() > 0 {
                let n = nodes.pop().unwrap_or(0)
                let d = depths.pop().unwrap_or(0)
                if d > best { best = d }
                if left[n as usize] >= 0 {
                    nodes.push(left[n as usize])
                    depths.push(d + 1)
                }
                if right[n as usize] >= 0 {
                    nodes.push(right[n as usize])
                    depths.push(d + 1)
                }
            }
            println("${best}")
        } else if cmd == "min" || cmd == "max" {
            if root < 0 {
                println("empty")
            } else {
                let mut cur = root
                if cmd == "min" {
                    while left[cur as usize] >= 0 { cur = left[cur as usize] }
                } else {
                    while right[cur as usize] >= 0 { cur = right[cur as usize] }
                }
                println("${keys[cur as usize]}")
            }
        }
    }
}

